def graph(mode):
    d=Drawing(485,245)
    svg=['<svg viewBox="0 0 485 245" xmlns="http://www.w3.org/2000/svg" role="img">']
    xmax=40 if mode=='normal' else 60
    ymax=30 if mode=='normal' else 100
    xticks=(15,25,40) if mode=='normal' else (15,25,40,60)
    yticks=range(0,31,5) if mode=='normal' else range(0,101,20)
    xp=lambda x:55+(x-15)/(xmax-15)*390
    yp=lambda y:43+y/ymax*150
    def line(x1,y1,x2,y2,col='#dddddd',width=.6):
        d.add(Line(x1,y1,x2,y2,strokeColor=colors.HexColor(col),strokeWidth=width))
        svg.append(f'<line x1="{x1}" y1="{245-y1}" x2="{x2}" y2="{245-y2}" stroke="{col}" stroke-width="{width}"/>')
    def label(x,y,s,size=10,anchor='middle'):
        d.add(String(x,y,s,fontName='Body',fontSize=size,textAnchor=anchor))
        svg.append(f'<text x="{x}" y="{245-y}" text-anchor="{anchor}" font-size="{size}" font-family="Georgia">{html.escape(s)}</text>')
    title='Своевременный goodput Normal' if mode=='normal' else 'Успешность '+mode.title()
    label(242,225,title,13)
    label(5,204,'запросов/с' if mode=='normal' else '%',10,'start')
    for y in yticks:
        line(55,yp(y),445,yp(y));label(47,yp(y)-3,str(y),9,'end')
    for x in xticks:label(xp(x),25,str(x))
    label(242,7,'Предложенная интенсивность RPS')
    for i,(strategy,col) in enumerate((('Adaptive','#24588a'),('Cinnamon','#ad5423'))):
        points=[]
        for rate in xticks:
            if mode=='normal':
                rr=[r for r in normal if r['strategy']==strategy and int(r['target_rps'])==rate]
                values=[float(r['actual_rps'])*float(r['timely_success_pct'])/100 for r in rr]
                val,lo,hi=statistics.median(values),min(values),max(values)
            else:
                r=next(r for r in priority if r['strategy']==strategy and int(r['rate'])==rate and r['priority']==mode)
                val,lo,hi=[float(r['success_pct_'+s]) for s in ('median','min','max')]
            x,y=xp(rate),yp(val)
            points.append((x,y))
            line(x,yp(lo),x,yp(hi),col,1)
            for bound in (lo,hi):line(x-3,yp(bound),x+3,yp(bound),col,1)
            d.add(Circle(x,y,3,fillColor=colors.HexColor(col),strokeColor=colors.HexColor(col)))
            svg.append(f'<circle cx="{x}" cy="{245-y}" r="3" fill="{col}"/>')
        for a,b in zip(points,points[1:]):line(*a,*b,col,1.5)
        xx=90+i*170
        line(xx,212,xx+18,212,col,2);label(xx+25,208,strategy,10,'start')
    svg.append('</svg>')
    return d,''.join(svg)

