def parse(content):
    lines=[x.strip() for x in content.strip().splitlines()]
    i=0
    while i<len(lines):
        l=lines[i]
        if not l:i+=1;continue
        if l.startswith('|'):
            rows=[]
            while i<len(lines) and lines[i].startswith('|'):
                rows.append(lines[i].strip('|').split('|'));i+=1
            yield ('table',rows);continue
        if l.startswith('@@'):yield ('h2',l[2:])
        elif l.startswith('@'):yield ('h1',l[1:])
        else:yield ('p',l)
        i+=1

def page(canvas,doc):
    canvas.setFont('Body',9)
    canvas.setFillColor(colors.HexColor('#666666'))
    canvas.drawCentredString(A4[0]/2,27,str(doc.page))

CSS='''@page{size:A4;margin:22mm 22mm 20mm}*{box-sizing:border-box}body{font:18px/1.6 Georgia,"Times New Roman",serif;color:#161616;background:#eee;margin:0}main{max-width:950px;margin:30px auto;background:white;padding:65px 75px}h1{font-size:32px;line-height:1.25}h2{font-size:25px;margin-top:38px;break-after:avoid}h3{font-size:21px;margin-top:28px;break-after:avoid}p{text-align:justify;margin:0 0 16px}table{border-collapse:collapse;width:100%;font-size:15px;line-height:1.4;margin:18px 0 25px;table-layout:fixed}td,th{border:1px solid #d9d9d9;padding:9px;overflow-wrap:anywhere}th{background:#e6edf3}tr{break-inside:avoid}.cover{padding:50px 0 40px}.sub{font-size:23px}.meta{color:#555;font-size:16px}nav{font-size:17px;line-height:1.8}a{color:#203b55}svg{width:100%;height:auto}@media print{body{background:white;font-size:12pt}main{padding:0;margin:0;max-width:none}.cover{break-after:page}nav{break-after:page}h2{font-size:16pt}h3{font-size:13pt}table{font-size:9pt}a{color:inherit;text-decoration:none}}'''

def build(stem,title,subtitle,content):
    blocks=list(parse(content))
    pdf=SimpleDocTemplate(str(OUT/(stem+'.pdf')),pagesize=A4,rightMargin=52,leftMargin=58,topMargin=48,bottomMargin=46,title=title,author='Svalinn')
    story=[Spacer(1,100),Paragraph(html.escape(title),styles['Cover']),Paragraph(html.escape(subtitle),styles['Sub']),Spacer(1,25),Paragraph('Проект Svalinn',styles['Sub']),Paragraph('2026',styles['Sub']),PageBreak(),Paragraph('Содержание',styles['H'])]
    toc=[v for t,v in blocks if t=='h1']
    for v in toc:story.append(Paragraph(html.escape(v),styles['Text']))
    story.append(PageBreak())
    out=[f'<!doctype html><html lang="ru"><meta charset="utf-8"><title>{html.escape(title)}</title><style>{CSS}</style><main><div class="cover"><h1>{html.escape(title)}</h1><p class="sub">{html.escape(subtitle)}</p><p>Проект Svalinn</p><p class="meta">2026</p></div><nav><h2>Содержание</h2>']
    for i,v in enumerate(toc):out.append(f'<div><a href="#s{i}">{html.escape(v)}</a></div>')
    out.append('</nav>')
    sid=0
    for kind,value in blocks:
        if kind=='h1':
            if stem=='Svalinn_Practice' and value.startswith('Источники'):
                story.append(PageBreak())
            story.append(Paragraph(html.escape(value),styles['H']))
            out.append(f'<h2 id="s{sid}">{html.escape(value)}</h2>');sid+=1
        elif kind=='h2':
            story.append(Paragraph(html.escape(value),styles['H2x']))
            out.append(f'<h3>{html.escape(value)}</h3>')
        elif kind=='table':
            n=len(value[0]); widths=([34,78,80,80,95,112] if n==6 else [35,90,99,110,145] if n==5 else [190,295] if n==2 else [100,190,189])
            widths=[x*485/sum(widths) for x in widths]
            data=[[Paragraph(html.escape(c),styles['Cellx']) for c in r] for r in value]
            table=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
            table.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e6edf3')),('GRID',(0,0),(-1,-1),.5,colors.HexColor('#d9d9d9')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6)]))
            story.extend([Spacer(1,4),table,Spacer(1,12)])
            out.append('<table>')
            for i,row in enumerate(value):out.append('<tr>'+''.join(f'<{"th" if i==0 else "td"}>{html.escape(c)}</{"th" if i==0 else "td"}>' for c in row)+'</tr>')
            out.append('</table>')
            if stem=='Svalinn_NIR' and len(value[0])>=5:
                modes=['normal'] if len(value[0])==5 else ['critical','high']
                for mode in modes:
                    chart,sv=graph(mode)
                    caption='Медианы двух повторов и диапазоны min–max. Линии соединяют проверенные уровни; значения между ними не измерялись.'
                    story.append(KeepTogether([chart,Paragraph(caption,styles['Smallx'])]))
                    out.append(sv+'<p class="meta">'+caption+'</p>')
        else:
            # Long technical paths can wrap without extending beyond the text area.
            escaped=html.escape(value).replace('/', '/\u200b')
            story.append(Paragraph(escaped,styles['Smallx'] if value.startswith('[') else styles['Text']))
            out.append('<p>'+html.escape(value)+'</p>')
    out.append('</main></html>')
    (OUT/(stem+'.html')).write_text('\n'.join(out),encoding='utf-8')
    pdf.build(story,onFirstPage=page,onLaterPages=page)
    print(stem,len(content.split()),'words')

build('Svalinn_NIR','Отчёт по НИР','Экспериментальное исследование механизмов приоритетного управления перегрузкой',nir)
build('Svalinn_Practice','Отчёт по практике','Развитие системы Svalinn и разработка стенда нагрузочных испытаний',practice)
(OUT/'sources.json').write_text(json.dumps({'as_of':'2026-11-18','normal_rows':len(normal),'priority_rows':len(priority),'checks':{'csharp':'PASS four groups','python':'35 tests OK project venv'},'notes':'Current series are kept separate from historical versions. Latency target and success ratio are separate criteria.'},ensure_ascii=False,indent=2),encoding='utf-8')
